import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('');
  const [selectedY, setSelectedY] = useState('');
  const [chartType, setChartType] = useState('ScatterChart');
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Fetch available columns on mount
  useEffect(() => {
    const fetchColumns = async () => {
      try {
        const response = await axios.get('http://localhost:8000/data/columns');
        if (response.data.columns && response.data.columns.length >= 2) {
          setColumns(response.data.columns);
          setSelectedX(response.data.columns[0]);
          setSelectedY(response.data.columns[1]);
          setError('');
        } else {
          setError('No columns available for visualization');
        }
      } catch (err) {
        setError('Failed to load column information');
        console.error(err);
      }
    };
    fetchColumns();
  }, []);

  // Generate chart data from backend
  const generateChart = async () => {
    if (!selectedX || !selectedY) {
      setError('Please select both X and Y axes');
      setData([]);
      return;
    }

    setIsLoading(true);
    setError('');

    try {
      const response = await axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY, limit: 100 }
      });

      if (!response.data || response.data.length === 0) {
        setError('No data available for selected columns');
        setData([]);
        setIsLoading(false);
        return;
      }

      // Prepare data for the chart library: first row is headers
      const chartData = [
        [selectedX, selectedY],
        ...response.data.map(item => [item[selectedX], item[selectedY]])
      ];

      setData(chartData);
      setError('');
    } catch (err) {
      setError('Failed to generate chart');
      setData([]);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  // Auto-generate chart when X or Y axis changes
  useEffect(() => {
    if (selectedX && selectedY) {
      generateChart();
    }
  }, [selectedX, selectedY]);

  return (
    <div className="visualization-container">
      <h2>Data Visualization</h2>

      <div className="controls">
        <div className="control-group">
          <label>X-Axis:</label>
          <select
            value={selectedX}
            onChange={e => setSelectedX(e.target.value)}
            disabled={isLoading}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label>Y-Axis:</label>
          <select
            value={selectedY}
            onChange={e => setSelectedY(e.target.value)}
            disabled={isLoading}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label>Chart Type:</label>
          <select
            value={chartType}
            onChange={e => setChartType(e.target.value)}
            disabled={isLoading}
          >
            <option value="ScatterChart">Scatter Chart</option>
            <option value="LineChart">Line Chart</option>
            <option value="BarChart">Bar Chart</option>
            <option value="Histogram">Histogram</option>
          </select>
        </div>
      </div>

      {error && <div className="error-message">{error}</div>}

      <div className="chart-container">
        {isLoading ? (
          <div className="loading">Loading chart data...</div>
        ) : data && Array.isArray(data) && data.length > 1 ? (
          <Chart
            chartType={chartType}
            width="100%"
            height="400px"
            data={data}
            options={{
              title: `${selectedY} vs ${selectedX}`,
              hAxis: { title: selectedX },
              vAxis: { title: selectedY },
              legend: { position: 'none' },
              chartArea: { width: '80%', height: '70%' },
            }}
          />
        ) : (
          <div className="no-data">
            {columns.length > 0
              ? 'Select columns to generate chart'
              : 'Loading columns...'}
          </div>
        )}
      </div>
    </div>
  );
}

export default Visualization;
